import { render, screen } from '@testing-library/react';
import { SeverityLevel } from '@microsoft/applicationinsights-common';
import { MemoryRouter } from 'react-router';
import { afterEach, describe, expect, it, vi } from 'vitest';
import ErrorBoundary from '@/components/ErrorBoundary';
import ErrorDisplay from '@/components/ErrorBoundary/ErrorDisplay';
import { HttpStatusCode } from '@/types';

const renderErrorDisplay = (status: HttpStatusCode | number) =>
  render(
    <MemoryRouter>
      <ErrorDisplay status={status} />
    </MemoryRouter>
  );

describe(ErrorDisplay, () => {
  afterEach(() => {
    document.body.className = '';
    document.title = '';
  });

  it.each([
    [
      HttpStatusCode.Conflict,
      'Oops - Conflict 409',
      'Conflict | NMI Services portal',
    ],
    [
      HttpStatusCode.Gone,
      'Oops - Not Available 410',
      'Not Available | NMI Services portal',
    ],
    [
      HttpStatusCode.NotFound,
      'Oops - Page not found 404',
      'Page not found | NMI Services portal',
    ],
    [
      HttpStatusCode.PreconditionFailed,
      'Oops - A precondition failed error has occurred 412',
      'Precondition Failed | NMI Services portal',
    ],
    [
      HttpStatusCode.ServiceUnavailable,
      'Oops - Service unavailable. 503',
      'Service Unavailable | NMI Services portal',
    ],
    [
      HttpStatusCode.UnprocessableEntity,
      'Oops - Unprocessable. 422',
      'Unprocessable | NMI Services portal',
    ],
    [
      HttpStatusCode.Forbidden,
      'Oops - Forbidden 403',
      'Forbidden | NMI Services portal',
    ],
    [
      HttpStatusCode.InternalServerError,
      'Oops - An unexpected error has occurred',
      'Server error | NMI Services portal',
    ],
    [
      599,
      'Oops - An unexpected error has occurred',
      'Server error | NMI Services portal',
    ],
  ])('renders the %s error state', (status, heading, title) => {
    renderErrorDisplay(status);

    expect(screen.getByRole('heading', { level: 1 })).toHaveAccessibleName(
      heading
    );
    expect(
      screen.getByRole('link', { name: 'Go to dashboard' })
    ).toHaveAttribute('href', '/');
    expect(
      screen.getByRole('link', { name: 'infotm@measurement.gov.au' })
    ).toHaveAttribute(
      'href',
      'mailto:infotm@measurement.gov.au?Subject=Error on NMI Services portal'
    );
    expect(document.title).toBe(title);
    expect(document.body).toHaveClass('http-error');
  });
});

describe(ErrorBoundary, () => {
  afterEach(() => {
    vi.restoreAllMocks();
  });

  const renderWithExpectedError = (
    expectedError: Error,
    ui: React.ReactElement
  ) => {
    const unexpectedConsoleErrors: unknown[][] = [];
    const preventExpectedError = (event: ErrorEvent) => {
      if (event.error === expectedError) {
        event.preventDefault();
      }
    };
    vi.spyOn(console, 'error').mockImplementation((...args: unknown[]) => {
      if (args.includes(expectedError)) {
        return;
      }

      unexpectedConsoleErrors.push(args);
    });
    globalThis.addEventListener('error', preventExpectedError);

    try {
      render(ui);
    } finally {
      globalThis.removeEventListener('error', preventExpectedError);
    }

    expect(unexpectedConsoleErrors).toEqual([]);
  };

  it('renders children when no error is thrown', () => {
    const trackException = vi.fn();
    const appInsights = {
      getAppInsights: () => ({ trackException }),
    };

    render(
      <MemoryRouter>
        <ErrorBoundary
          appInsights={
            appInsights as unknown as React.ComponentProps<
              typeof ErrorBoundary
            >['appInsights']
          }
        >
          <p>Healthy child</p>
        </ErrorBoundary>
      </MemoryRouter>
    );

    expect(screen.getByText('Healthy child')).toBeInTheDocument();
    expect(trackException).not.toHaveBeenCalled();
  });

  it('renders the fallback when telemetry is disabled', () => {
    const expectedError = Object.assign(new Error('Request failed'), {
      status: HttpStatusCode.Conflict,
    });
    const ThrowingChild = () => {
      throw expectedError;
    };

    // createTelemetryService hands back a null reactPlugin whenever the App
    // Insights connection string is missing or dummy - every environment
    // without telemetry configured. The boundary is the last line of
    // defence, so it has to render its fallback rather than throw from
    // inside its own error handler.
    renderWithExpectedError(
      expectedError,
      <MemoryRouter>
        <ErrorBoundary
          appInsights={
            null as unknown as React.ComponentProps<
              typeof ErrorBoundary
            >['appInsights']
          }
        >
          <ThrowingChild />
        </ErrorBoundary>
      </MemoryRouter>
    );

    expect(screen.getByRole('heading', { level: 1 })).toHaveAccessibleName(
      'Oops - Conflict 409'
    );
  });

  it('renders the fallback and tracks an exception when a child throws', () => {
    const expectedError = Object.assign(new Error('Request failed'), {
      status: HttpStatusCode.Conflict,
    });
    const ThrowingChild = () => {
      throw expectedError;
    };
    const trackException = vi.fn();
    const appInsights = {
      getAppInsights: () => ({ trackException }),
    };

    renderWithExpectedError(
      expectedError,
      <MemoryRouter>
        <ErrorBoundary
          appInsights={
            appInsights as unknown as React.ComponentProps<
              typeof ErrorBoundary
            >['appInsights']
          }
        >
          <ThrowingChild />
        </ErrorBoundary>
      </MemoryRouter>
    );

    expect(
      screen.getByRole('heading', { level: 1, name: /Oops - Conflict/i })
    ).toBeInTheDocument();
    expect(trackException).toHaveBeenCalledWith(
      expect.objectContaining({
        error: expectedError,
        exception: expectedError,
        severityLevel: SeverityLevel.Error,
        properties: expect.objectContaining({
          componentStack: expect.any(String),
        }),
      })
    );
  });

  it('uses the server-error fallback when a thrown error has no status', () => {
    const expectedError = new Error('Unknown failure');
    const ThrowingChild = () => {
      throw expectedError;
    };
    const appInsights = {
      getAppInsights: () => ({ trackException: vi.fn() }),
    };

    renderWithExpectedError(
      expectedError,
      <MemoryRouter>
        <ErrorBoundary
          appInsights={
            appInsights as unknown as React.ComponentProps<
              typeof ErrorBoundary
            >['appInsights']
          }
        >
          <ThrowingChild />
        </ErrorBoundary>
      </MemoryRouter>
    );

    expect(
      screen.getByRole('heading', {
        level: 1,
        name: /Oops - An unexpected error has occurred/i,
      })
    ).toBeInTheDocument();
  });

  it('wraps a non-Error throw into an Error before tracking it', () => {
    const thrown = 'plain string failure';
    const ThrowingChild = () => {
      throw thrown;
    };
    const trackException = vi.fn();
    const appInsights = {
      getAppInsights: () => ({ trackException }),
    };

    // react-error-boundary v6 surfaces the raw thrown value (here a string),
    // so the boundary must normalise it to an Error before reporting. React
    // logs its own error for the uncaught throw; suppress it for this
    // deliberate failure so the test only asserts the normalisation.
    const preventError = (event: ErrorEvent) => {
      event.preventDefault();
    };
    vi.spyOn(console, 'error').mockImplementation(() => {});
    globalThis.addEventListener('error', preventError);

    try {
      render(
        <MemoryRouter>
          <ErrorBoundary
            appInsights={
              appInsights as unknown as React.ComponentProps<
                typeof ErrorBoundary
              >['appInsights']
            }
          >
            <ThrowingChild />
          </ErrorBoundary>
        </MemoryRouter>
      );
    } finally {
      globalThis.removeEventListener('error', preventError);
    }

    const [trackedException] = trackException.mock.calls[0] as [
      { error: Error; exception: Error; severityLevel: SeverityLevel },
    ];

    expect(trackedException.error).toBeInstanceOf(Error);
    expect(trackedException.exception).toBe(trackedException.error);
    expect(trackedException.error.message).toBe('plain string failure');
    expect(trackedException.severityLevel).toBe(SeverityLevel.Error);
  });
});

import { readFileSync } from 'node:fs';

import type { ViteUserConfig } from 'vitest/config';
import { describe, expect, it, vi } from 'vitest';

vi.mock(
  '@storybook/addon-vitest/vitest-plugin',
  () =>
    ({
      storybookTest: vi.fn(() => ({ name: 'storybook-test-mock' })),
    }) satisfies __ExactMockModule<__TestMockModule56>
);

import rootConfig from '../../../vitest.config';
import storybookConfig from '../../../vitest.storybook.config';
import unitConfig from '../../../vitest.unit.config';

/**
 * Characterization of the committed Vitest topology (fix `0d16927`).
 *
 * Vitest 4 ignores a nested `test.projects` container when that config is itself
 * referenced as a root project, which previously caused unit files to be
 * discovered a second time without jsdom. The root config is composition only;
 * each leaf owns its own environment, coverage, browser and worker settings.
 *
 * A failure here means the committed topology drifted — investigate before
 * editing any Vitest configuration.
 */

type TestOptions = NonNullable<ViteUserConfig['test']>;

type PackageScripts = { scripts: Record<string, string> };

const testOptions = (config: ViteUserConfig, label: string): TestOptions => {
  const options = config.test;

  if (options === undefined) {
    throw new Error(`${label} must declare a test block`);
  }

  return options;
};

const root = testOptions(rootConfig, 'vitest.config.ts');
const storybook = testOptions(storybookConfig, 'vitest.storybook.config.ts');
const unit = testOptions(unitConfig, 'vitest.unit.config.ts');
const packageScripts = (): Record<string, string> =>
  (JSON.parse(readFileSync('package.json', 'utf8')) as PackageScripts).scripts;
const vitestConfigContents: Record<string, string> = {
  'vitest.config.ts': readFileSync('vitest.config.ts', 'utf8'),
  'vitest.unit.config.ts': readFileSync('vitest.unit.config.ts', 'utf8'),
};
/** Paths that belong to Playwright, never to a Vitest leaf. */
const foreignTestPaths = [
  '.github/migration-verifier/tests/runtime/checklist.runtime.spec.ts',
  'tests/e2e/example.feature',
  'tests/e2e/steps/example.steps.ts',
];

describe('root Vitest config is composition only', () => {
  it('declares exactly the two leaf projects in order', () => {
    expect(root.projects).toEqual([
      './vitest.unit.config.ts',
      './vitest.storybook.config.ts',
    ]);
  });

  it('does not own a worker cap that would starve the browser pool', () => {
    expect(root.maxWorkers).toBeUndefined();
  });

  it('does not own leaf-specific environment, coverage or browser settings', () => {
    expect(root.environment).toBeUndefined();
    expect(root.coverage).toBeUndefined();
    expect(root.browser).toBeUndefined();
    expect(root.setupFiles).toBeUndefined();
  });
});

describe('vitest config loading stays explicit and shim-free', () => {
  it('pins every package script that invokes Vitest to the runner config loader', () => {
    const vitestScripts = Object.entries(packageScripts()).filter(
      ([, command]) => command.includes('./node_modules/vitest/vitest.mjs')
    );

    expect(vitestScripts.length).toBeGreaterThan(0);

    for (const [name, command] of vitestScripts) {
      expect(
        command,
        `${name} must not rely on Vite's default config loader`
      ).toContain('--configLoader runner');
    }
  });

  it.each(['vitest.config.ts', 'vitest.unit.config.ts'])(
    "does not rely on the bundled config loader's __dirname shim in %s",
    (configFile) => {
      const configContents = Object.entries(vitestConfigContents)
        .find(([name]) => name === configFile)
        ?.at(1);

      expect(configContents).not.toContain('__dirname');
    }
  );
});

describe('storybook leaf is a directly runnable Browser Mode project', () => {
  it('is a leaf rather than another nested project container', () => {
    expect(storybook.projects).toBeUndefined();
  });

  it('owns Chromium Browser Mode', () => {
    expect(storybook.browser?.enabled).toBe(true);
    expect(storybook.browser?.headless).toBe(true);
    expect(storybook.browser?.instances).toEqual([{ browser: 'chromium' }]);
  });

  it('limits the persistent MCP runner to one browser orchestrator', () => {
    expect(storybook.maxWorkers).toBe(1);
  });

  it('owns its own name and setup file', () => {
    expect(storybook.name).toBe('storybook');
    expect(storybook.setupFiles).toEqual(['./vitest.storybook.setup.ts']);
  });

  it('does not explicitly prebundle modular Lodash entry points', () => {
    const include = storybookConfig.optimizeDeps?.include ?? [];

    expect(
      include.some(
        (entry) => typeof entry === 'string' && entry.startsWith('lodash/')
      )
    ).toBe(false);
  });

  it("pins Browser Mode API binding out of Windows' reserved TCP ranges (below the 49152 dynamic range)", () => {
    expect(storybook.api).toBeUndefined();
    expect(storybook.browser?.api).toMatchObject({
      host: '127.0.0.1',
      port: 47005,
    });
  });

  it('owns the Storybook coverage policy for the one path that applies it', () => {
    // Vitest 4 resolves coverage from the ROOT config only
    // (vitest/dist/chunks/cli-api...js, `get _coverageOptions()`). This block
    // therefore applies when `--config vitest.storybook.config.ts` makes this
    // file the root - i.e. the `test:storybook` script - and is inert when the
    // project is loaded through the aggregate `vitest.config.ts`.
    expect(storybook.coverage?.reportsDirectory).toBe(
      './reports/coverage/storybook'
    );
    expect(storybook.coverage?.include).toEqual([
      'ClientApp/src/**/*.{ts,tsx}',
    ]);
  });

  it('never lets a script enable coverage through the aggregate root config', () => {
    // Where project coverage is inert, enabling coverage would silently fall
    // back to Vitest defaults - reinstating the JSON remap failure and dropping
    // the unit config's 100% thresholds - with nothing to signal it.
    expect(root.coverage).toBeUndefined();

    const { scripts } = JSON.parse(
      readFileSync('package.json', 'utf8')
    ) as PackageScripts;

    const reviewedCoverageConfigs = new Set([
      'vitest.unit.config.ts',
      'vitest.storybook.config.ts',
    ]);
    const aggregateRunsWithCoverage = Object.entries(scripts).filter(
      ([, command]) => {
        if (!command.includes('--coverage')) {
          return false;
        }

        const config = /--config(?:=|\s+)([^\s]+)/.exec(command)?.[1];

        return config === undefined || !reviewedCoverageConfigs.has(config);
      }
    );

    expect(aggregateRunsWithCoverage).toEqual([]);
  });
});

describe('unit leaf owns jsdom, unit discovery and unit coverage', () => {
  it('runs in jsdom', () => {
    expect(unit.environment).toBe('jsdom');
  });

  it('discovers only unit test files', () => {
    expect(unit.include).toEqual(['tests/unit/**/*.test.{ts,tsx}']);
  });

  it('owns the worker cap rather than inheriting one from the root', () => {
    expect(unit.maxWorkers).toBe(2);
  });

  it('owns unit coverage reporting', () => {
    expect(unit.coverage?.reportsDirectory).toBe('./reports/coverage/unit');
  });

  it('does not enable Browser Mode', () => {
    expect(unit.browser?.enabled).toBeUndefined();
  });
});

describe('playwright files stay out of both Vitest leaves', () => {
  it.each(foreignTestPaths)('does not discover %s', (foreignPath) => {
    for (const pattern of unit.include ?? []) {
      expect(
        foreignPath.startsWith(pattern.split('*', 1)[0] ?? pattern),
        `unit include "${pattern}" must not reach ${foreignPath}`
      ).toBe(false);
    }
  });

  it('leaves Storybook discovery to the storybookTest plugin', () => {
    expect(unit.include).not.toContain('**/*.stories.tsx');
    expect(storybook.include).toBeUndefined();
  });
});
